CREATE TABLE IF NOT EXISTS users (username TEXT PRIMARY KEY, password TEXT, displayName TEXT, email TEXT, profileImage TEXT, role TEXT, permissions TEXT[], passwordChanged BOOLEAN, emailSet BOOLEAN);\nCREATE TABLE IF NOT EXISTS reset_tokens (username TEXT PRIMARY KEY, token TEXT, expires TIMESTAMP);\nCREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, title TEXT, type TEXT, dueDate TEXT, serviceType TEXT, description TEXT, priority TEXT, status TEXT, hardwareSpecs JSONB, boards JSONB, repairDetails JSONB);\nCREATE TABLE IF NOT EXISTS materials (id TEXT PRIMARY KEY, name TEXT, supplier TEXT, suppliers TEXT[], receptionDate TEXT, minQuantity INTEGER, maxQuantity INTEGER, currentQuantity INTEGER, linkedProject TEXT, linkedOrder TEXT, category TEXT, location TEXT, unit TEXT, cost FLOAT, barcode TEXT, lastUpdated TIMESTAMP, image TEXT);\nCREATE TABLE IF NOT EXISTS material_transactions (id TEXT PRIMARY KEY, materialId TEXT, materialName TEXT, type TEXT, quantity INTEGER, date TIMESTAMP, reason TEXT, userId TEXT, supplier TEXT, projectId TEXT, orderId TEXT);\nCREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, userId TEXT, description TEXT, materials JSONB, status TEXT, date TIMESTAMP, folderId TEXT);\nCREATE TABLE IF NOT EXISTS order_folders (id TEXT PRIMARY KEY, name TEXT, color TEXT);\nCREATE TABLE IF NOT EXISTS tests (id TEXT PRIMARY KEY, title TEXT, description TEXT, category TEXT, equipment TEXT, steps JSONB, files JSONB, createdAt TIMESTAMP, updatedAt TIMESTAMP);
